package com.bananalab.lite;
import java.util.*;import org.json.*;
public class Stage37Check{
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 static SceneDraft apply(CreatorSession c,Semilla m,String q,SceneDraft d)throws Exception{CreatorSession.Result r=c.apply(m,q,d);check(r.commit!=null,q+" => "+r.text);return r.commit;}
 public static void main(String[] args)throws Exception{Semilla m=SemillaCheck.load(args[0]+"/assets/language");CreatorSession c=new CreatorSession();SceneDraft d=apply(c,m,"crea a Tony una banana azul detective con sobretodo; agrega un pepino llamado Milo; agrega un tomate llamado Nora",null);
  d=apply(c,m,"selecciona a Tony",d);d=apply(c,m,"selecciona a Milo",d);check(d.previousFocus.equals("banana"),"previous focus");d=SceneDraft.read(d.json().toString());d=apply(c,m,"hace al anterior mas alto",d);check(d.get("banana").look.contains("alto")&&!d.get("pepino").look.contains("alto"),"previous reference grounded and persisted");d=apply(c,m,"hace ese con ojos grandes",d);check(d.get("banana").look.contains("ojos grandes"),"focused ese");
  SceneDraft before=d.copy();String milo=d.json().getJSONArray("cast").getJSONObject(1).toString(),nora=d.json().getJSONArray("cast").getJSONObject(2).toString();int body=Scene.bodyColor("banana",d.get("banana").look);d=apply(c,m,"cambia solo el sombrero de Tony por una corona y deja todo lo demas igual",d);check(d.get("banana").look.contains("corona")&&!d.get("banana").look.contains("sombrero")&&d.get("banana").look.contains("sobretodo"),"scoped hat swap");check(d.get("banana").designId.equals(before.get("banana").designId)&&body==Scene.bodyColor("banana",d.get("banana").look)&&d.actions.equals(before.actions)&&d.setting.equals(before.setting),"identity/body/actions/background preserved");check(milo.equals(d.json().getJSONArray("cast").getJSONObject(1).toString())&&nora.equals(d.json().getJSONArray("cast").getJSONObject(2).toString()),"other designs unchanged");check(c.apply(m,"cambia su sombrero a rojo",d).commit==null,"unsupported part color not approximated by body recolor");
  d=apply(c,m,"Tony baila",d);SceneDraft initial=d.copy();d=apply(c,m,"continua con Tony saluda mientras Milo salta y despues Nora camina",d);check(d.actions.size()==4&&d.actions.get(0).equals(initial.actions.get(0))&&d.slot(0)==initial.slot(0)&&d.slot(1)>initial.slot(0),"continuation preserves prefix");check(d.get("banana").designId.equals(initial.get("banana").designId),"continuation identity");d=apply(c,m,"reemplaza la secuencia con Tony saluda",d);check(d.actions.size()==1&&d.actions.get(0).equals("saluda")&&d.get("banana").designId.equals(initial.get("banana").designId),"explicit replacement differs from append");
  d=apply(c,m,"Tony entrega una caja a Milo",d);SceneDraft first=d.copy();d=apply(c,m,"continua con Milo entrega la caja a Nora",d);check(SceneResolver.received(d,"caja","banana",false)==d.get("pepino"),"recipient event not final owner");check(SceneResolver.special(d,"el que tiene la caja")==d.get("tomate"),"final owner grounded");check(SceneGuide.reply("quien recibio la caja de Tony",d).contains("milo"),"event question answered from timeline");check(SceneGuide.reply("quien tiene la caja",d).contains("nora"),"owner question answered from timeline");
  d=apply(c,m,"hace al que recibio la caja de Tony mas bajo",d);check(d.get("pepino").look.contains("bajo")&&!d.get("tomate").look.contains("bajo"),"event reference edits intended recipient");String saved=d.json().toString();check(c.apply(m,"continua con Tony entrega la caja a Milo",d).commit==null&&saved.equals(d.json().toString()),"nonowner cannot transfer, no partial continuation");check(c.apply(m,"Tony salta mientras Tony baila",d).commit==null,"incompatible simultaneous actions clarified");check(c.apply(m,"hace al otro mas alto",d).commit==null,"ambiguous other remains unchanged");
  SceneDraft broken=d.copy();int receive=-1;for(int i=0;i<broken.actions.size();i++)if(broken.actions.get(i).equals("recibe")){receive=i;break;}broken.actions.set(receive,"saluda");check(SceneConsistency.problem(broken)!=null,"orphan handoff detected");SceneDraft wrong=d.copy();wrong.prop("caja").holder="tomate";check(SceneConsistency.problem(wrong)!=null,"initial ownership contradiction detected");
  SceneDraft floor=initial.copy();floor.actions.clear();floor.actors.clear();floor.slots.clear();floor.targets.clear();floor.recipients.clear();SceneDirector.object(floor,"caja");check(c.apply(m,"Tony entrega la caja a Milo",floor).commit==null,"existing unowned object requires pickup");floor=apply(c,m,"Tony sostiene la caja",floor);floor=apply(c,m,"continua con Tony entrega la caja a Milo",floor);check(SceneConsistency.problem(floor)==null,"explicit pickup followed by valid transfer");
  CreatorPersistenceCheck.Fake ctx=new CreatorPersistenceCheck.Fake();CreatorMemory.save(ctx,c,d);SceneDraft persisted=SceneStore.load(ctx);check(persisted.previousFocus.equals(d.previousFocus),"reference focus metadata persists");String stored=persisted.json().toString();BananaEngine.Result rejected=BananaEngine.run(ctx,"continua con Tony entrega la caja a Milo",new ArrayList<String[]>(),"",true,m);check(!rejected.changed&&SceneStore.load(ctx).json().toString().equals(stored),"persistent engine rollback");
  System.out.println("PASS discourse references, scoped edits, append/replacement, chronological ownership, contradictions, ambiguity and persistent rollback");
 }
}
